CREATE TABLE public.ai_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ai_threads TO authenticated;
GRANT ALL ON public.ai_threads TO service_role;
ALTER TABLE public.ai_threads ENABLE ROW LEVEL SECURITY;
CREATE POLICY ai_threads_own_read ON public.ai_threads FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE UNIQUE INDEX ai_threads_one_active ON public.ai_threads(user_id) WHERE archived_at IS NULL;
CREATE TABLE public.ai_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES public.ai_threads(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('user','assistant','tool')), content text NOT NULL DEFAULT '', tool_calls jsonb, tool_call_id text, tool_name text, case_ids uuid[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ai_messages TO authenticated;
GRANT ALL ON public.ai_messages TO service_role;
ALTER TABLE public.ai_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY ai_messages_own_read ON public.ai_messages FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.ai_threads t WHERE t.id=thread_id AND t.user_id=auth.uid()));
CREATE INDEX ai_messages_thread_date ON public.ai_messages(thread_id,created_at);
CREATE TABLE public.ai_usage (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, thread_id uuid, message_id uuid, model text NOT NULL, prompt_tokens int NOT NULL DEFAULT 0, completion_tokens int NOT NULL DEFAULT 0, total_tokens int GENERATED ALWAYS AS (prompt_tokens+completion_tokens) STORED, tool_calls int NOT NULL DEFAULT 0, rounds int NOT NULL DEFAULT 0, duration_ms int, status text NOT NULL DEFAULT 'ok' CHECK(status IN ('ok','limit','error','disabled')), error text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ai_usage TO authenticated;
GRANT ALL ON public.ai_usage TO service_role;
ALTER TABLE public.ai_usage ENABLE ROW LEVEL SECURITY;
CREATE POLICY ai_usage_read ON public.ai_usage FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.auth_is_admin() OR public.auth_user_role()='coordinator');
CREATE INDEX ai_usage_user_date ON public.ai_usage(user_id,created_at);
CREATE INDEX ai_usage_date ON public.ai_usage(created_at);
CREATE TABLE public.ai_settings (id int PRIMARY KEY DEFAULT 1 CHECK(id=1), enabled boolean NOT NULL DEFAULT true, model text NOT NULL, daily_message_limit int NOT NULL DEFAULT 40 CHECK(daily_message_limit>=0), extra_instructions text, updated_at timestamptz NOT NULL DEFAULT now(), gateway_error text, gateway_status int);
GRANT SELECT ON public.ai_settings TO authenticated;
GRANT UPDATE(enabled,model,daily_message_limit,extra_instructions,updated_at,gateway_error,gateway_status) ON public.ai_settings TO authenticated;
GRANT ALL ON public.ai_settings TO service_role;
ALTER TABLE public.ai_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY ai_settings_read ON public.ai_settings FOR SELECT TO authenticated USING (true);
CREATE POLICY ai_settings_admin_update ON public.ai_settings FOR UPDATE TO authenticated USING(public.auth_is_admin()) WITH CHECK(public.auth_is_admin());
CREATE TRIGGER ai_settings_touch BEFORE UPDATE ON public.ai_settings FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER ai_threads_touch BEFORE UPDATE ON public.ai_threads FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE FUNCTION public.ai_archive_thread() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Du måste vara inloggad'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0)); UPDATE public.ai_threads SET archived_at=now() WHERE user_id=auth.uid() AND archived_at IS NULL; END $$;
REVOKE ALL ON FUNCTION public.ai_archive_thread() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.ai_archive_thread() TO authenticated;
CREATE FUNCTION public.ai_begin_message(p_user_id uuid,p_message text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t uuid; m uuid; n int; s public.ai_settings%ROWTYPE; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(p_user_id::text,0)); SELECT * INTO STRICT s FROM public.ai_settings WHERE id=1; IF NOT s.enabled THEN RETURN jsonb_build_object('status','disabled'); END IF; SELECT count(*) INTO n FROM public.ai_messages a JOIN public.ai_threads b ON b.id=a.thread_id WHERE b.user_id=p_user_id AND a.role='user' AND a.created_at>=date_trunc('day',now() AT TIME ZONE 'Europe/Stockholm') AT TIME ZONE 'Europe/Stockholm'; IF n>=s.daily_message_limit THEN RETURN jsonb_build_object('status','limit'); END IF; SELECT id INTO t FROM public.ai_threads WHERE user_id=p_user_id AND archived_at IS NULL; IF t IS NULL THEN INSERT INTO public.ai_threads(user_id,title) VALUES(p_user_id,'N3prenad-AI') RETURNING id INTO t; END IF; INSERT INTO public.ai_messages(thread_id,role,content) VALUES(t,'user',p_message) RETURNING id INTO m; UPDATE public.ai_threads SET updated_at=now() WHERE id=t; RETURN jsonb_build_object('status','ok','thread_id',t,'message_id',m); END $$;
REVOKE ALL ON FUNCTION public.ai_begin_message(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ai_begin_message(uuid,text) TO service_role;